-- QWIZ-PARTY Phase 6 first verified batch: find the only falsely captioned national flag.
-- Each row: 4 different *genuine* flag SVGs; 3 matching country captions, 1 false caption.
-- This avoids inaccurate digital manipulations of official flag symbols.
begin;
do $seed$
declare t uuid;o uuid;r record;sol jsonb;corrected jsonb;cnt integer;
begin
 select id,owner_id into t,o from public.qwiz_topics where name='Флаги мира';
 if t is null then raise exception 'Flags category unavailable';end if;
