 ) as seed(iso,real_name,wrong_caption,correct_index,answers) loop
   sol:=jsonb_build_object('flag_mode','errors','error_kind','mislabeled','correct',r.correct_index);
   if not public.qwiz_flags_question_valid('flag',r.answers,sol) then raise exception 'Invalid item for %',r.iso;end if;
   if r.answers->r.correct_index->>'label'<>r.wrong_caption then raise exception 'Wrong caption index mismatch';end if;
   if r.answers->r.correct_index->>'image_url' not like '%/'||lower(r.iso)||'.svg' then raise exception 'Wrong national flag at correct position';end if;
   if not exists(select 1 from public.qwiz_bank b where b.topic_id=t and b.solution->>'flag_mode'='errors' and 'iso:'||r.iso=any(b.tags)) then
    insert into public.qwiz_bank(owner_id,topic_id,kind,prompt,options,solution,explanation,difficulty,tags)
    values(o,t,'flag','Найдите ошибку: под каким из четырёх флагов неверно указана страна?',
      r.answers,sol,'Ошибка в варианте '||chr(65+r.correct_index)||': на изображении флаг государства «'||r.real_name||'», а указанная подпись — «'||r.wrong_caption||'».',3,
      array['fw:published','fw:errors-stage6','iso:'||r.iso,'source:local-svg']);
   end if;
 end loop;
 select count(*) into cnt from public.qwiz_bank b where b.topic_id=t and 'fw:errors-stage6'=any(b.tags);
 if cnt<>24 then raise exception 'Expected 24 stage-6 questions, found %',cnt;end if;
end $seed$;
commit;